LLM_output:
def largest(lst):
    m = lst[0]
    for x in lst:
        if x > m:
            m = x
    return m

def remove_duplicates(lst):
    seen = set()
    out = []
    for x in lst:
        if x not in seen:
            seen.add(x)
            out.append(x)
    return out

import re
def word_freq(s):
    words = re.findall(r'[a-z0-9]+', s.lower())
    freq = {}
    for w in words:
        freq[w] = freq.get(w, 0) + 1
    return freq

def mean_numeric(strings):
    nums = []
    for s in strings:
        try:
            nums.append(float(s))
        except ValueError:
            pass
    if not nums:
        raise ValueError('No valid numbers')
    return sum(nums) / len(nums)

def flatten(lst):
    out = []
    for x in lst:
        if isinstance(x, list):
            out.extend(flatten(x))
        else:
            out.append(x)
    return out

def second_largest(lst):
    first = second = None
    for x in lst:
        if first is None or x > first:
            second = first
            first = x
        elif x < first and (second is None or x > second):
            second = x
    if second is None:
        raise ValueError('Need at least two distinct numbers')
    return second

def group_by_first(words):
    groups = {}
    for w in words:
        if not w:
            continue
        key = w[0].lower()
        groups.setdefault(key, []).append(w)
    return groups

def balanced(s):
    stack = []
    for c in s:
        if c == '(':
            stack.append(c)
        elif c == ')':
            if not stack:
                return False
            stack.pop()
    return not stack

def group_anagrams(words):
    groups = {}
    for w in words:
        key = ''.join(sorted(w.lower()))
        groups.setdefault(key, []).append(w)
    return list(groups.values())
# The key is the sorted lowercase letters of the word.

from collections import OrderedDict

class LRUCache:
    def __init__(self, capacity):
        self.capacity = capacity
        self.cache = OrderedDict()

    def get(self, key):
        if key not in self.cache:
            return -1
        self.cache.move_to_end(key)
        return self.cache[key]

    def put(self, key, value):
        if key in self.cache:
            self.cache.move_to_end(key)
        self.cache[key] = value
        if len(self.cache) > self.capacity:
            self.cache.popitem(last=False)

def linear_search(lst, target):
    for i, x in enumerate(lst):
        if x == target:
            return i
    return -1

def factorial(n):
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result

def reverse_string(s):
    result = ''
    for c in s:
        result = c + result
    return result

def binary_search(lst, target):
    lo, hi = 0, len(lst) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if lst[mid] == target:
            return mid
        elif lst[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

def merge_sorted(a, b):
    i = j = 0
    out = []
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            out.append(a[i])
            i += 1
        else:
            out.append(b[j])
            j += 1
    out.extend(a[i:])
    out.extend(b[j:])
    return out

def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return False
    return True
# We only check up to sqrt(n) because any factor larger than sqrt(n) pairs with one smaller.

def longest_unique_substring(s):
    seen = {}
    start = 0
    max_len = 0
    for i, c in enumerate(s):
        if c in seen and seen[c] >= start:
            start = seen[c] + 1
        seen[c] = i
        max_len = max(max_len, i - start + 1)
    return max_len
# Sliding window: expand right, move left past duplicates. Time O(n).

from collections import deque

def bfs_path(graph, start, end):
    if start == end:
        return [start]
    queue = deque([[start]])
    visited = {start}
    while queue:
        path = queue.popleft()
        node = path[-1]
        for nxt in graph.get(node, []):
            if nxt == end:
                return path + [nxt]
            if nxt not in visited:
                visited.add(nxt)
                queue.append(path + [nxt])
    return None

The default list is created once and shared across calls. Fix by using None:
def add_item(item, items=None):
    if items is None:
        items = []
    items.append(item)
    return items

For n = 0 and negatives, the base case never triggers, causing infinite recursion. Corrected:
def factorial(n):
    if n < 0:
        raise ValueError('negative')
    if n in (0, 1):
        return 1
    return n * factorial(n - 1)
